# Copies the GS-related parts of PCSX2's pcsx2/Pcsx2Config.cpp into compat/Pcsx2ConfigGS.cpp (constructors of the
# option structs, GSOptions helpers, the name tables), so EmuConfig/GSConfig exist without the rest of the emulator.
import re, sys
src_path, out_path = sys.argv[1], sys.argv[2]
src = open(src_path, encoding='utf-8').read()
lines = src.split('\n')

def block_from(start_pattern):
    for i, line in enumerate(lines):
        if line.startswith(start_pattern):
            depth = 0; seen = False; out = []
            for j in range(i, len(lines)):
                out.append(lines[j])
                depth += lines[j].count('{') - lines[j].count('}')
                if '{' in lines[j]: seen = True
                if seen and depth == 0:
                    return '\n'.join(out)
    raise SystemExit('not found: ' + start_pattern)

wanted = [
    'TraceLogsEE::TraceLogsEE()',
    'TraceLogsIOP::TraceLogsIOP()',
    'TraceLogsMISC::TraceLogsMISC()',
    'TraceLogFilters::TraceLogFilters()',
    'Pcsx2Config::SpeedhackOptions::SpeedhackOptions()',
    'Pcsx2Config::SpeedhackOptions& Pcsx2Config::SpeedhackOptions::DisableAll()',
    'Pcsx2Config::GamefixOptions& Pcsx2Config::GamefixOptions::DisableAll()',
    'Pcsx2Config::SPU2Options::SPU2Options()',
    'Pcsx2Config::DEV9Options::DEV9Options()',
    'Pcsx2Config::ProfilerOptions::ProfilerOptions()',
    'Pcsx2Config::RecompilerOptions::RecompilerOptions()',
    'Pcsx2Config::CpuOptions::CpuOptions()',
    'Pcsx2Config::GSOptions::GSOptions()',
    'Pcsx2Config::GamefixOptions::GamefixOptions()',
    'Pcsx2Config::SavestateOptions::SavestateOptions()',
    'Pcsx2Config::FilenameOptions::FilenameOptions()',
    'Pcsx2Config::EmulationSpeedOptions::EmulationSpeedOptions()',
    'Pcsx2Config::USBOptions::USBOptions()',
    'Pcsx2Config::AchievementsOptions::AchievementsOptions()',
    'const char* Pcsx2Config::GSOptions::GetRendererName(',
    'bool Pcsx2Config::GSOptions::RestartOptionsAreEqual(',
    'bool Pcsx2Config::GSOptions::ShouldDump(',
]
# Name tables: every "const char* Pcsx2Config::GSOptions::xxx[...] = {" definition.
tables = []
for i, line in enumerate(lines):
    if re.match(r'const char\* Pcsx2Config::GSOptions::[A-Za-z]+\[', line) or re.match(r'const char\* Pcsx2Config::GSOptions::[A-Z_]+ = ', line):
        if line.rstrip().endswith(';'):
            tables.append(line)
        else:
            tables.append(block_from(line) + ';' if not block_from(line).rstrip().endswith(';') else block_from(line))
out = ['// Generated by tools/extract_config.py from PCSX2 pcsx2/Pcsx2Config.cpp (GPL-3): the option constructors and GS',
       '// helpers PCSX2\'s GS needs. Pcsx2Config() and PadOptions() are written by hand in HostStubs.cpp (no memory cards/pads).',
       '#include "Config.h"', '#include "GS/GS.h"', '#include "common/StringUtil.h"', '#include "fmt/format.h"', '']
# The helpers above the first definition: OpEqu and the default FPU/VU control registers.
a = next(i for i, l in enumerate(lines) if l.startswith('#define OpEqu'))
b = next(i for i, l in enumerate(lines) if l.startswith('static constexpr FPControlRegister DEFAULT_VU_FP_CONTROL_REGISTER'))
while not lines[b].rstrip().endswith(';'):
    b += 1
out += lines[a:b + 1] + ['']
out += tables + ['']
for w in wanted:
    out += [block_from(w), '']
open(out_path, 'w', encoding='utf-8', newline='\n').write('\n'.join(out))
print('wrote', out_path, len(tables), 'tables', len(wanted), 'functions')
